NODE_PATH=$(npm root -g) node -e "
const db = require('better-sqlite3')('/workspace/world.db');
// Check users table schema
const schema = db.prepare(\"PRAGMA table_info(users)\").all();
console.log('users columns:', schema.map(c=>c.name));
// Search for Sofia Martinez
const rows = db.prepare(\"SELECT * FROM users WHERE name LIKE '%Sofia%' OR name LIKE '%Martinez%'\").all();
console.log('Matching users:', JSON.stringify(rows, null, 2));
"

